/**
 * The Nirmaan mark, as a data URI: the letterhead and the watermark of the
 * week-resource document (weekResource.js).
 *
 * The bytes live here rather than in public/ because that document is written
 * into a blank window — and sometimes downloaded and opened from disk — where a
 * URL into the app's origin resolves to nothing. Vite's `?inline` only inlines
 * CSS and workers, and `vite dev` serves assets as URLs whatever the config
 * says, so inlining it at build time is not an option either.
 *
 * Cut from src/assets/nirmaan-mark.png — the course logo, trimmed to its art,
 * 900px wide, 255-colour palette. The white SURROUND is flood-filled away from
 * the border rather than every white pixel being cleared, so the knockout
 * “SOCH SE VIKAS” keeps its own white on the cream footer. After a logo
 * change, replace that file and regenerate this one:
 *   node -e "console.log(require('fs').readFileSync('src/assets/nirmaan-mark.png','base64'))"
 */
export const NIRMAAN_MARK = 'data:image/png;base64,'

/**
 * The course logo as the week resource's page watermark: the same file the
 * Nirmaan page's hero shows, public/NirmaanLogo.png — the one whose strap reads
 * "SOCH SE VIKAS". Not nirmaan-vertical.png, which reads "SOCH SE VIKAS TAK"
 * and is the wrong wording.
 *
 * Cut from src/assets/nirmaan-watermark.png (that file trimmed to its art,
 * 1000px wide). Regenerate the same way as the mark above.
 */
export const NIRMAAN_WATERMARK = 'data:image/png;base64,'
